1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Calculator</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body {
10	    margin: 0; min-height: 100vh; display: flex; align-items: center; justify-content: center;
11	    background: #eceef1; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
12	  }
13	  .calc {
14	    width: min(320px, 100vw - 32px); padding: 16px; border-radius: 20px;
15	    background: #1f2227; box-shadow: 0 12px 32px rgba(0,0,0,.25);
16	  }
17	  .display {
18	    height: 80px; margin-bottom: 16px; padding: 0 12px; border-radius: 12px;
19	    background: #2b2f36; color: #fff; font-size: 40px; text-align: right;
20	    line-height: 80px; overflow: hidden; white-space: nowrap; text-overflow: ellipsis;
21	  }
22	  .keys { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; }
23	  button {
24	    height: 60px; border: 0; border-radius: 12px; font-size: 22px; cursor: pointer;
25	    background: #3a3f47; color: #fff;
26	  }
27	  button:active { filter: brightness(1.25); }
28	  .op { background: #f59e0b; }
29	  .clear { background: #9ca3af; color: #111; }
30	  .wide { grid-column: span 2; }
31	</style>
32	</head>
33	<body>
34	<div class="calc">
35	  <div class="display" data-testid="calc-display" data-value="0" data-error="false">0</div>
36	  <div class="keys">
37	    <button class="clear" data-testid="key-clear">AC</button>
38	    <button class="clear" data-testid="key-sign">±</button>
39	    <button class="clear" data-testid="key-percent">%</button>
40	    <button class="op" data-testid="key-div" data-op="/">÷</button>
41	    <button data-testid="key-7" data-digit="7">7</button>
42	    <button data-testid="key-8" data-digit="8">8</button>
43	    <button data-testid="key-9" data-digit="9">9</button>
44	    <button class="op" data-testid="key-mul" data-op="*">×</button>
45	    <button data-testid="key-4" data-digit="4">4</button>
46	    <button data-testid="key-5" data-digit="5">5</button>
47	    <button data-testid="key-6" data-digit="6">6</button>
48	    <button class="op" data-testid="key-sub" data-op="-">−</button>
49	    <button data-testid="key-1" data-digit="1">1</button>
50	    <button data-testid="key-2" data-digit="2">2</button>
51	    <button data-testid="key-3" data-digit="3">3</button>
52	    <button class="op" data-testid="key-add" data-op="+">+</button>
53	    <button class="wide" data-testid="key-0" data-digit="0">0</button>
54	    <button data-testid="key-dot">.</button>
55	    <button class="op" data-testid="key-equals">=</button>
56	  </div>
57	</div>
58	<script>
59	  var entry = "0";      // text of the current entry or last result
60	  var stored = null;    // left operand
61	  var op = null;        // pending operator
62	  var fresh = true;     // next digit starts a new entry
63	  var waiting = false;  // an operator was just pressed and has no right operand yet
64	  var error = false;    // set by a non-finite result; only clear leaves it
65	
66	  var display = document.querySelector('[data-testid="calc-display"]');
67	
68	  function compute(a, b, o) {
69	    if (o === "+") return a + b;
70	    if (o === "-") return a - b;
71	    if (o === "*") return a * b;
72	    return a / b;
73	  }
74	
75	  // Presentation only: at most 10 significant digits, no trailing zeros,
76	  // exponential below 1e-9 or from 1e10. Stored values are never rounded.
77	  function format(v) {
78	    if (v === 0) return "0";
79	    var r = Number(v.toPrecision(10));
80	    var a = Math.abs(r);
81	    if (a >= 1e10 || a < 1e-9) return r.toExponential();
82	    var e = Math.floor(Math.log10(a));
83	    if (Math.pow(10, e) > a) e--;
84	    var s = r.toFixed(Math.max(0, 9 - e));
85	    return s.indexOf(".") === -1 ? s : s.replace(/0+$/, "").replace(/\.$/, "");
86	  }
87	
88	  // While typing, the entry shows exactly as typed; results are formatted.
89	  function render() {
90	    display.textContent = error ? "Error" : fresh ? format(Number(entry)) : entry;
91	    display.setAttribute("data-value", String(Number(entry)));
92	    display.setAttribute("data-error", String(error));
93	  }
94	
95	  function digit(d) {
96	    if (fresh) { entry = d; fresh = false; }
97	    else entry = entry === "0" || entry === "-0" ? entry.slice(0, -1) + d : entry + d;
98	    waiting = false;
99	  }
100	
101	  function dot() {
102	    if (fresh) { entry = "0."; fresh = false; }
103	    else if (entry.indexOf(".") === -1) entry += ".";
104	    waiting = false;
105	  }
106	
107	  // Acts on the current entry. A typed entry keeps its text; a result is negated as a value.
108	  function sign() {
109	    if (!fresh) entry = entry.charAt(0) === "-" ? entry.slice(1) : "-" + entry;
110	    else entry = String(-Number(entry));
111	    waiting = false;
112	  }
113	
114	  // Acts on the current entry; the result is a value, so the next digit starts a new entry.
115	  function percent() {
116	    entry = String(Number(entry) / 100);
117	    fresh = true;
118	    waiting = false;
119	  }
120	
121	  // Immediate execution: each operator finishes the waiting operation, strictly
122	  // left to right, no precedence. 2 + 3 × 4 = is 20. The display always shows a real result.
123	  function operator(o) {
124	    if (op !== null && !waiting) finish(compute(stored, Number(entry), op));
125	    stored = Number(entry);
126	    op = o;
127	    fresh = true;
128	    waiting = true;
129	  }
130	
131	  // Division by zero (or any non-finite result) enters the error state.
132	  function finish(result) {
133	    entry = String(result);
134	    if (!isFinite(result)) error = true;
135	  }
136	
137	  function equals() {
138	    if (op === null) return;
139	    finish(compute(stored, Number(entry), op));
140	    stored = null;
141	    op = null;
142	    fresh = true;
143	    waiting = false;
144	  }
145	
146	  function clear() {
147	    entry = "0"; stored = null; op = null; fresh = true; waiting = false; error = false;
148	  }
149	
150	  document.querySelector(".keys").addEventListener("click", function (e) {
151	    var b = e.target.closest("button");
152	    if (!b) return;
153	    var id = b.getAttribute("data-testid");
154	    if (error && id !== "key-clear") return;
155	    if (b.hasAttribute("data-digit")) digit(b.getAttribute("data-digit"));
156	    else if (b.hasAttribute("data-op")) operator(b.getAttribute("data-op"));
157	    else if (id === "key-dot") dot();
158	    else if (id === "key-sign") sign();
159	    else if (id === "key-percent") percent();
160	    else if (id === "key-equals") equals();
161	    else if (id === "key-clear") clear();
162	    render();
163	  });
164	
165	  render();
166	</script>
167	</body>
168	</html>
